import math

def clamp_unit(x: float) -> float | None:
    if math.isnan(x) or math.isinf(x) or x < 0:
        return None
    if x <= 1:
        return x
    elif x <= 10:
        return x / 10
    elif x <= 100:
        return x / 100
    else:
        return None

import pytest

def test_clamp_unit():
    assert clamp_unit(5) == 0.5
    assert clamp_unit(50) == 0.5
    assert clamp_unit(100) == 1.0
    assert clamp_unit(101) is None
    assert clamp_unit(-5) is None
    assert clamp_unit(float('nan')) is None
    assert clamp_unit(0.0) == 0.0
    assert clamp_unit(1.0) == 1.0

